head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00053";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — resultDiv, registYn, messageStr

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00053.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_12", grids: ["grd_checkList"], fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '6'); } }, { id: "c_otherwise_23", fn: function(){ return (!(((dma_pageContext.get("resultDiv") ?? "") === '6'))); } }, { id: "btn_reUpload", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2' || (dma_pageContext.get("resultDiv") ?? "") === '6'); } }, { id: "c_otherwise_30", fn: function(){ return (!(((dma_pageContext.get("resultDiv") ?? "") === '2' || (dma_pageContext.get("resultDiv") ?? "") === '6'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "- " + String(String((dma_pageContext.get("transMessage") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00053.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil00053: 진입 키 disclosureexl#excelpop 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_reUpload_onclick
 * @description 「다시 업로드하기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_reUpload_onclick = async function(e){
    try {
        await scwin.reUpload()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00053.btn_reUpload_onclick' }); }
};

/**
 * @method
 * @name btn_linkDocument_onclick
 * @description 「문서작성바로가기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_linkDocument_onclick = function(e){
    try {
        scwin.linkDocument()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00053.btn_linkDocument_onclick' }); }
};

/**
 * @method
 * @name btn_closePop_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_closePop_onclick = function(e){
    try {
        scwin.close_pop()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00053.btn_closePop_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ElwExcelUpload
 * @description Elw Excel Upload 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ElwExcelUpload = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwExcelUpload",
        method: "post",
        action: "/submission/disclosureExl.do?method=excelUpload",
        ref: "dma_ElwExcelUploadReq",
        target: "",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        {
            const d = $c.util.getComponent("dlt_checkList");
            const a = (res && res.responseJSON && res.responseJSON.body && res.responseJSON.body.content) || [];
            if (!d || !d.setJSON) { /* TODO Stage2: [sdd] 구분자 열 채우기 대상 없음: dlt_checkList */ }
            else { d.setJSON(a.map(function (v) {
                            const p = String(v == null ? '' : (v && v.value !== undefined ? v.value : v)).split("_!::!_");
                            return { c0: p[0] || '', c1: p[1] || '', c2: p[2] || '', c3: p[3] || '', c4: p[4] || '' };
                })); }
        }
    }
    return res;
};

/**
 * @method
 * @name tx_fn_reUpload
 * @description re Upload 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_reUpload = async function () {
    const sbmOptions = {
        id: "tx_fn_reUpload",
        method: "post",
        action: "/submission/disclosureExl.do?method=excelPop",
        ref: "dma_reUploadReq",
        target: "dlt_checkList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name elwExcelUpload
 * @description elw Excel Upload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwExcelUpload = async function () {
    const form = (document.disclosureFrm || { elements: [] });
    if (await $c.win.confirm("업로드 하시겠습니까?")) {
        await $c.win.alert('upload시작');
        form.action = "/submission/disclosureExl.do?method=excelUpload";
        await scwin.tx_fn_ElwExcelUpload();
    }
};

/**
 * @method
 * @name reUpload
 * @description re Upload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reUpload = async function () {
    (document.disclosureFrm || { elements: [] }).action = '/submission/disclosureExl.do?method=excelPop';
    await scwin.tx_fn_reUpload();

};

/**
 * @method
 * @name linkDocument
 * @description link Document 처리
 * @returns {void}
 * @hidden N
 */
scwin.linkDocument = function () {
    if ((String(((dma_pageContext.get("registYn") ?? "")) == null ? '' : ((dma_pageContext.get("registYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("registYn") ?? "")) == null ? '' : ((dma_pageContext.get("registYn") ?? "")))) === 'Y' && $c.util.getComponent('ipt_applNo').getValue().length === 14) {
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).fn_linkOpen === 'function' ? (scwin.openerScwin()).fn_linkOpen($c.util.getComponent('ipt_applNo').getValue(), '' + dma_docVo.get("docNo") + '', $c.util.getComponent('ipt_formCd').getValue(), $c.util.getComponent('ipt_formVer').getValue(), $c.util.getComponent('ipt_wrtrptMaindocTpCd').getValue(), '' + dma_pageContext.get("method") + '') : void 0), $c.win.closePopup([$c.util.getComponent('ipt_applNo').getValue(), '' + dma_docVo.get("docNo") + '', $c.util.getComponent('ipt_formCd').getValue(), $c.util.getComponent('ipt_formVer').getValue(), $c.util.getComponent('ipt_wrtrptMaindocTpCd').getValue(), '' + dma_pageContext.get("method") + '']));
    } else {
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).registerMessage === 'function' ? (scwin.openerScwin()).registerMessage((String(((dma_pageContext.get("messageStr") ?? "")) == null ? '' : ((dma_pageContext.get("messageStr") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("messageStr") ?? "")) == null ? '' : ((dma_pageContext.get("messageStr") ?? ""))))) : void 0), $c.win.closePopup([(String(((dma_pageContext.get("messageStr") ?? "")) == null ? '' : ((dma_pageContext.get("messageStr") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("messageStr") ?? "")) == null ? '' : ((dma_pageContext.get("messageStr") ?? ""))))]));
    }
    scwin.close_pop();
};

/**
 * @method
 * @name close_pop
 * @description close pop 처리
 * @returns {void}
 * @hidden N
 */
scwin.close_pop = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
